class OrderingTest {
    private val me = "Alice"

    private fun msg(
        id: String,
        from: String = me,
        to: String = "Bob",
        seq: Long? = null,
        createdAt: String,
        receivedAt: String? = null,
        status: MessageStatus = if (seq == null) MessageStatus.QUEUED else MessageStatus.SENT,
    ) = Message(id, "text", from, to, "body-$id", createdAt, seq, receivedAt, status, null)

    /** REQ-ORDER-001: seq ascending first, then unsequenced by createdAt, ties by id. */
    @Test
    fun `REQ-ORDER-001 thread order is seq first, then createdAt, then id`() {
        val messages = listOf(
            msg("q2", createdAt = "2026-10-15T10:00:00.002Z"),
            msg("s5", seq = 5, createdAt = "2026-10-15T12:00:00.000Z", receivedAt = "2026-10-15T12:00:00.000Z"),
            msg("f1", createdAt = "2026-10-15T10:00:00.001Z", status = MessageStatus.FAILED),
            msg("s2", from = "Bob", to = me, seq = 2, createdAt = "2026-10-15T13:00:00.000Z", receivedAt = "2026-10-15T13:00:00.000Z"),
            msg("qb", createdAt = "2026-10-15T10:00:00.002Z"),
            msg("qa", createdAt = "2026-10-15T10:00:00.002Z"),
            msg("other", to = "Carol", seq = 1, createdAt = "2026-10-15T09:00:00.000Z"),
        )
        val thread = ObserveThreadUseCase.thread(messages.shuffled(), me, "Bob")
        assertEquals(listOf("s2", "s5", "f1", "q2", "qa", "qb"), thread.map { it.id })
    }

    /** REQ-ORDER-002: newest activity first (receivedAt, else createdAt), ties by peer name. */
    @Test
    fun `REQ-ORDER-002 conversations are ordered by last activity, newest first, ties by peer`() {
        val messages = listOf(
            msg("b1", from = "Bob", to = me, seq = 1, createdAt = "2026-10-15T10:00:00.000Z", receivedAt = "2026-10-15T10:00:01.000Z"),
            msg("c1", from = "Carol", to = me, seq = 2, createdAt = "2026-10-15T10:00:00.000Z", receivedAt = "2026-10-15T10:00:02.000Z"),
            // Dave's only message is queued: its activity time is its createdAt.
            msg("d1", to = "Dave", createdAt = "2026-10-15T10:00:01.500Z"),
            // Erin ties with Carol on activity time; ties go by peer name ascending.
            msg("e1", from = "Erin", to = me, seq = 3, createdAt = "2026-10-15T09:00:00.000Z", receivedAt = "2026-10-15T10:00:02.000Z"),
        )
        val conversations = ObserveConversationsUseCase.conversations(messages, me)
        assertEquals(listOf("Carol", "Erin", "Dave", "Bob"), conversations.map { it.peer })
        assertEquals("c1", conversations.first().lastMessage.id)
    }

    /** REQ-ORDER-002: the last message is chosen in REQ-ORDER-001 order, not by time. */
    @Test
    fun `REQ-ORDER-002 last message follows thread order`() {
        val messages = listOf(
            msg("s1", from = "Bob", to = me, seq = 1, createdAt = "2026-10-15T10:00:00.000Z", receivedAt = "2026-10-15T10:00:00.000Z"),
            // Queued after the sequenced one in thread order, even with an older createdAt.
            msg("q1", createdAt = "2026-10-15T08:00:00.000Z"),
        )
        val conversation = ObserveConversationsUseCase.conversations(messages, me).single()
        assertEquals("q1", conversation.lastMessage.id)
    }

    /** Scenario conversation-order: Bob, then Carol, then Bob again. */
    @Test
    fun `REQ-ORDER-002 scenario conversation-order`() {
        val first = listOf(
            msg("b1", from = "Bob", to = me, seq = 1, createdAt = "2026-10-15T10:00:00.000Z", receivedAt = "2026-10-15T10:00:00.010Z"),
            msg("c1", from = "Carol", to = me, seq = 2, createdAt = "2026-10-15T10:00:01.000Z", receivedAt = "2026-10-15T10:00:01.010Z"),
        )
        assertEquals(listOf("Carol", "Bob"), ObserveConversationsUseCase.conversations(first, me).map { it.peer })
        val second = first + msg("b2", from = "Bob", to = me, seq = 3, createdAt = "2026-10-15T10:00:02.000Z", receivedAt = "2026-10-15T10:00:02.010Z")
        assertEquals(listOf("Bob", "Carol"), ObserveConversationsUseCase.conversations(second, me).map { it.peer })
